<template>
  <span class="priority-icon-wrapper">
    <q-icon :name="iconName" :color="iconColor" :size="iconSize">
      <q-tooltip>{{ priorityLabel }}</q-tooltip>
    </q-icon>
    <span v-if="showLabel" class="q-ml-xs">{{ priorityLabel }}</span>
  </span>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export interface PriorityConfig {
  icon: string;
  color: string;
}

const PRIORITY_MAP: Record<string, PriorityConfig> = {
  critical: { icon: 'warning', color: 'negative' },
  high: { icon: 'keyboard_arrow_up', color: 'negative' },
  medium: { icon: 'remove', color: 'orange-8' },
  low: { icon: 'keyboard_arrow_down', color: 'info' },
};

export default defineComponent({
  name: 'PriorityIcon',
  props: {
    priority: {
      type: String,
      required: true,
    },
    size: {
      type: String as PropType<'sm' | 'md'>,
      default: 'sm',
    },
    showLabel: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    config(): PriorityConfig {
      return PRIORITY_MAP[this.priority] || PRIORITY_MAP.medium;
    },
    iconName(): string {
      return this.config.icon;
    },
    iconColor(): string {
      return this.config.color;
    },
    iconSize(): string {
      return this.size === 'md' ? '20px' : '16px';
    },
    priorityLabel(): string {
      return this.priority.charAt(0).toUpperCase() + this.priority.slice(1);
    },
  },
});
</script>

<style scoped>
.priority-icon-wrapper {
  display: inline-flex;
  align-items: center;
}
</style>
